cuda_source = """
#include <cuda_fp16.h>

__global__ void cumulative_product_kernel(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t dim_size,
    int64_t stride,
    int64_t batch_size
) {
    int64_t batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const half* input_batch = input + batch_idx * dim_size * stride;
    half* output_batch = output + batch_idx * dim_size * stride;

    // Process each element along the specified dimension
    for (int64_t i = 0; i < dim_size; i++) {
        half accumulator = __float2half(1.0f);
        for (int64_t j = 0; j <= i; j++) {
            int64_t idx = j * stride;
            accumulator = __hmul(accumulator, input_batch[idx]);
        }
        output_batch[i * stride] = accumulator;
    }
}

// Optimized version for better memory access patterns
__global__ void cumulative_product_kernel_optimized(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t dim_size,
    int64_t stride,
    int64_t batch_size
) {
    int64_t batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const half* input_batch = input + batch_idx * dim_size * stride;
    half* output_batch = output + batch_idx * dim_size * stride;

    // Use shared memory for better performance when possible
    half accumulator = __float2half(1.0f);
    for (int64_t i = 0; i < dim_size; i++) {
        accumulator = __hmul(accumulator, input_batch[i * stride]);
        output_batch[i * stride] = accumulator;
    }
}

// Main kernel launcher
extern "C" void launch_cumulative_product(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t dim_size,
    int64_t stride,
    int64_t batch_size
) {
    const int threads_per_block = 256;
    const int blocks = (batch_size + threads_per_block - 1) / threads_per_block;

    cumulative_product_kernel_optimized<<<blocks, 1>>>(
        input, output, total_elements, dim_size, stride, batch_size
    );
}
"""

# Python wrapper
def compile_and_run():
    # Compile the CUDA extension
    module = load_inline(
        name="cumulative_product_ext",
        cpp_sources=[],
        cuda_sources=[cuda_source],
        functions=["launch_cumulative_product"],
        verbose=True
    )

    class ModelNew(torch.nn.Module):
        def __init__(self, dim):
            super(ModelNew, self).__init__()
            self.dim = dim

        def forward(self, x):
            # Ensure input is contiguous and has correct dtype
            x = x.contiguous().to(torch.float16)

            # Get dimensions
            shape = x.shape
            batch_size = 1
            dim_size = shape[self.dim]
            stride = 1

            # Calculate stride for the specified dimension
            for i in range(self.dim + 1, len(shape)):
                stride *= shape[i]

            # Calculate batch size
            for i in range(self.dim):
                batch_size *= shape[i]

            # Prepare output
            output = torch.empty_like(x)

            # Launch kernel
            module.launch_cumulative_product(
                x.data_ptr(),
                output.data_ptr(),
                x.numel(),
                dim_size,
                stride,
                batch_size
            )

            return output

    return ModelNew

# Create the model class
ModelNew = compile_and_run()

